import hashlib
import hmac
import os
import json
import time
import sqlite3
from functools import wraps
from flask import Flask, request, jsonify, g
import bcrypt

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)

# Permission levels stored as integers
# 0=guest, 1=user, 2=moderator, 3=admin, 4=superadmin
PERMISSION_NAMES = ['guest', 'user', 'moderator', 'admin', 'superadmin']

# Action permission matrix - each action requires minimum permission level
ACTION_PERMISSIONS = {
    'read': 0,
    'write': 1,
    'delete': 2,
    'manage_users': 3,
    'system_config': 4
}

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(':memory:')
        g.db.row_factory = sqlite3.Row
        init_db(g.db)
    return g.db

def init_db(db):
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        permission_level INTEGER NOT NULL DEFAULT 1,
        department TEXT NOT NULL DEFAULT 'general'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        user_id INTEGER,
        action TEXT,
        target TEXT,
        timestamp REAL,
        result TEXT
    )''')
    # Create default admin
    pw_hash = bcrypt.hashpw(b'admin_pass_change_me', bcrypt.gensalt()).decode()
    db.execute('INSERT OR IGNORE INTO users (username, password_hash, permission_level, department) VALUES (?, ?, ?, ?)',
               ('admin', pw_hash, 4, 'engineering'))
    db.commit()

def create_token(user_id, permission_level):
    payload = json.dumps({'uid': user_id, 'perm': permission_level, 'exp': time.time() + 3600})
    signature = hmac.new(app.config['SECRET_KEY'], payload.encode(), hashlib.sha256).hexdigest()
    return payload + '.' + signature

def verify_token(token):
    try:
        parts = token.rsplit('.', 1)
        if len(parts) != 2:
            return None
        payload, signature = parts
        expected = hmac.new(app.config['SECRET_KEY'], payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return None
        data = json.loads(payload)
        if data.get('exp', 0) < time.time():
            return None
        return data
    except Exception:
        return None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'unauthorized'}), 401
        token_data = verify_token(auth_header[7:])
        if not token_data:
            return jsonify({'error': 'invalid token'}), 401
        g.current_user = token_data
        return f(*args, **kwargs)
    return decorated

def audit_log(user_id, action, target, result):
    db = get_db()
    db.execute('INSERT INTO audit_log (user_id, action, target, timestamp, result) VALUES (?, ?, ?, ?, ?)',
               (user_id, action, target, time.time(), result))
    db.commit()

def check_permission(user_perm_level, required_action):
    """Check if user has sufficient permission for the action.
    Returns True if permitted, False otherwise.

    Permission levels are validated against the PERMISSION_NAMES array
    to ensure the level corresponds to a valid role name.
    """
    required_level = ACTION_PERMISSIONS.get(required_action)
    if required_level is None:
        return False

    # Validate that the permission level is within valid bounds
    if not isinstance(user_perm_level, int) or user_perm_level < 0 or user_perm_level > 4:
        return False

    # User's level must meet or exceed the required level
    if user_perm_level >= required_level:
        return True
    return False

def get_effective_permission(user_id, context=None):
    """Calculate effective permission considering delegation chains.
    Supports permission elevation through department-based trust."""
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return 0

    base_level = user['permission_level']

    # Department heads get +1 elevation in their own department context
    if context and context.get('department') == user['department']:
        if context.get('is_dept_action', False):
            base_level = min(base_level + 1, 4)

    return base_level

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'missing credentials'}), 400

    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ?', (data['username'],)).fetchone()
    if not user:
        return jsonify({'error': 'invalid credentials'}), 401

    if not bcrypt.checkpw(data['password'].encode('utf-8'), user['password_hash'].encode('utf-8')):
        return jsonify({'error': 'invalid credentials'}), 401

    token = create_token(user['id'], user['permission_level'])
    return jsonify({'token': token, 'role': PERMISSION_NAMES[user['permission_level']]})

@app.route('/api/users', methods=['POST'])
@require_auth
def create_user():
    if not check_permission(g.current_user['perm'], 'manage_users'):
        audit_log(g.current_user['uid'], 'create_user', 'denied', 'insufficient_permission')
        return jsonify({'error': 'forbidden'}), 403

    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'missing fields'}), 400

    # New user permission level from request, default to 1 (user)
    new_perm = data.get('permission_level', 1)

    # Validate permission level is a valid integer in range
    if not isinstance(new_perm, int) or new_perm < 0 or new_perm > 4:
        return jsonify({'error': 'invalid permission level'}), 400

    # Ensure creator cannot create users with higher permissions than themselves
    if new_perm > g.current_user['perm']:
        return jsonify({'error': 'cannot elevate beyond own level'}), 403

    db = get_db()
    pw_hash = bcrypt.hashpw(data['password'].encode('utf-8'), bcrypt.gensalt()).decode()
    try:
        db.execute('INSERT INTO users (username, password_hash, permission_level, department) VALUES (?, ?, ?, ?)',
                   (data['username'], pw_hash, new_perm, data.get('department', 'general')))
        db.commit()
        audit_log(g.current_user['uid'], 'create_user', data['username'], 'success')
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username exists'}), 409

@app.route('/api/system/config', methods=['POST'])
@require_auth
def update_system_config():
    """Update system configuration - requires superadmin."""
    perm_level = g.current_user['perm']

    if not check_permission(perm_level, 'system_config'):
        audit_log(g.current_user['uid'], 'system_config', 'denied', 'insufficient_permission')
        return jsonify({'error': 'forbidden'}), 403

    data = request.get_json()
    if not data or 'key' not in data or 'value' not in data:
        return jsonify({'error': 'missing fields'}), 400

    # Apply configuration (simplified)
    allowed_keys = ['max_upload_size', 'session_timeout', 'maintenance_mode']
    if data['key'] not in allowed_keys:
        return jsonify({'error': 'invalid config key'}), 400

    audit_log(g.current_user['uid'], 'system_config', data['key'], 'success')
    return jsonify({'status': 'updated', 'key': data['key'], 'value': data['value']})

@app.route('/api/actions/execute', methods=['POST'])
@require_auth
def execute_action():
    """Execute a privileged action with permission checking."""
    data = request.get_json()
    if not data or 'action' not in data:
        return jsonify({'error': 'missing action'}), 400

    action = data['action']
    context = data.get('context', {})

    # Get effective permission considering context
    effective_perm = get_effective_permission(g.current_user['uid'], context)

    if not check_permission(effective_perm, action):
        audit_log(g.current_user['uid'], action, 'denied', 'insufficient_permission')
        return jsonify({'error': 'forbidden'}), 403

    audit_log(g.current_user['uid'], action, json.dumps(context), 'success')
    return jsonify({'status': 'executed', 'action': action})

@app.route('/api/users/<int:user_id>/permission', methods=['PUT'])
@require_auth
def update_permission(user_id):
    """Update a user's permission level."""
    if not check_permission(g.current_user['perm'], 'manage_users'):
        return jsonify({'error': 'forbidden'}), 403

    data = request.get_json()
    if not data or 'permission_level' not in data:
        return jsonify({'error': 'missing permission_level'}), 400

    new_level = data['permission_level']

    # Strict type and range validation
    if not isinstance(new_level, int) or new_level < 0 or new_level > 4:
        return jsonify({'error': 'invalid permission level'}), 400

    # Validate: cannot set permission higher than own
    if new_level > g.current_user['perm']:
        return jsonify({'error': 'cannot elevate beyond own level'}), 403

    db = get_db()
    db.execute('UPDATE users SET permission_level = ? WHERE id = ?', (new_level, user_id))
    db.commit()

    audit_log(g.current_user['uid'], 'update_permission', str(user_id), f'set_to_{new_level}')
    return jsonify({'status': 'updated'})

if __name__ == '__main__':
    app.run(debug=False)
